//--------------------------------------------------------------------------//

void dei_rs_start_only( void )
{	
	if( !dei_rs_state ) //---> remote start off 
	{
		cmd_q_rs_insert(INPUT_RF_START_STOP_TOOGLE,200);
	}
}
//--------------------------------------------------------------------------//

void dei_rs_stop_only( void  )
{	
	if( dei_rs_state ) //---> remote start on
	{
		cmd_q_rs_insert(INPUT_RF_START_STOP_TOOGLE,200);
	}
}
//--------------------------------------------------------------------------//

void dei_rs_start_stop_from_smartstart( void )
{
	 cmd_q_rs_insert(INPUT_RF_START_STOP_TOOGLE,200);	
}

